import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Object3D();
  container.position.set(2.5, -0.2, 0);

  const timelines = [];

  // Load GLB mesh
  const gltf = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
  const mesh = gltf.scene.clone();

  // Reset mesh transform to origin
  mesh.position.set(0, 0, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  container.add(mesh);

  // Add accent rim light (signal red #ff2a38) for capsule definition
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.65);
  rimLight.position.set(2.5, 1.5, 2.5);
  container.add(rimLight);

  // Add fill light for depth and contrast
  const fillLight = new THREE.DirectionalLight(0xffffff, 0.7);
  fillLight.position.set(-1.5, 1, 2);
  container.add(fillLight);

  // Ambient light for base illumination
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
  container.add(ambientLight);

  // Weighted-settle entrance animation (overshoot 1.04 -> 1.0, power4.out, 0.9s)
  const entranceTimeline = gsap.timeline();
  mesh.scale.set(1.04, 1.04, 1.04);
  mesh.position.y = 0.25;

  entranceTimeline.to(mesh.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  entranceTimeline.to(mesh.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  timelines.push(entranceTimeline);

  // Hover animation: rise-in (y +0.15, power3.out, 0.7s)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: 0.15,
    duration: 0.7,
    ease: 'power3.out'
  });
  timelines.push(hoverTimeline);

  // Event handlers
  container.userData.handlers = {
    hover: (isHovering) => {
      if (isHovering) {
        hoverTimeline.play();
      } else {
        hoverTimeline.reverse();
      }
    },
    click: () => {
      if (config.context?.eventEmitter) {
        config.context.eventEmitter.emit('hub-journal.select');
      }
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](container, primitive.params || {});
      }
    });
  }

  // Cleanup function
  container.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());

    mesh?.traverse(node => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(m => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return container;
}
